use vstd::prelude::*;

verus! {

    // Specification: Set A contains these uppercase letters
    spec fn in_set_a(c: char) -> bool {
        c == 'A' ||
        c == 'E' ||
        c == 'F' ||
        c == 'H' ||
        c == 'I' ||
        c == 'K' ||
        c == 'L' ||
        c == 'M' ||
        c == 'N' ||
        c == 'T' ||
        c == 'V' ||
        c == 'W' ||
        c == 'X' ||
        c == 'Y' ||
        c == 'Z'
    }

    // Specification: Set B contains these uppercase letters
    spec fn in_set_b(c: char) -> bool {
        c == 'B' ||
        c == 'C' ||
        c == 'D' ||
        c == 'G' ||
        c == 'J' ||
        c == 'O' ||
        c == 'P' ||
        c == 'Q' ||
        c == 'R' ||
        c == 'S' ||
        c == 'U'
    }

    // solve returns "YES" iff all letters of word lie entirely in Set A or entirely in Set B,
    // otherwise returns "NO".
    fn solve(word: Vec<char>) -> (result: Vec<char>)
        requires
            // Length between 1 and 10
            1 <= word.len() && word.len() <= 10,
            // All characters are uppercase 'A'..'Z'
            forall(|i: usize| i < word.len() ==> word[i] >= 'A' && word[i] <= 'Z'),
        ensures
            // result == ["Y","E","S"] exactly when the word is all in A or all in B;
            // otherwise result == ["N","O"].
            result == if
                (forall(|j: usize| j < word.len() ==> in_set_a(word[j])))
                ||
                (forall(|j: usize| j < word.len() ==> in_set_b(word[j])))
            {
                vec!['Y','E','S']
            } else {
                vec!['N','O']
            },
    {
        // We track two booleans: all_a and all_b.
        // all_a : so far, every processed letter belongs to Set A
        // all_b : so far, every processed letter belongs to Set B
        let mut i: usize = 0;
        let mut all_a: bool = true;
        let mut all_b: bool = true;

        // Process the word character by character
        while i < word.len()
            invariant i <= word.len()
            invariant all_a == (forall(|j: usize| j < i ==> in_set_a(word[j])))
            invariant all_b == (forall(|j: usize| j < i ==> in_set_b(word[j])))
            decreases word.len() - i
        {
            let c = word[i];
            // update the flags
            all_a = all_a && in_set_a(c);
            all_b = all_b && in_set_b(c);
            i = i + 1;
        }

        // At the end, if either all_a or all_b holds for the whole word, return "YES"
        if all_a || all_b {
            vec!['Y','E','S']
        } else {
            vec!['N','O']
        }
    }

} // end of verus! block

